import React from "react";
import { AbsoluteFill, Audio, Easing, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { FONT } from "./kit";
import { IconeForca } from "./kitSite";
import { Check, CINZA, Entrada, estiloEntrada, F, Foto, k, LADO, Linhas, mola, PAPEL, Pilula, Tela, TINTA, TR } from "./kitReel";

// VITA (SAPIANS) — reel 3 de novembro "Liberdade" v2 humanizado (19/11/2026), mesma identidade do reel 2 v3 (kitReel)
// mas com composição própria, para não parecer o mesmo vídeo: a foto que alarga em "margem", tela dividida
// hoje/depois, folha de meses por cima da foto, rede de fotos, faixas de foto empilhadas, números em linha no claro e
// os ícones das forças no fecho. Transições também diferentes (divide, desce, gira…). Narração no ElevenLabs v3
// (o locutor, voz-v3.mp3, 51,8 s); tempos da transcrição, conferidos pelos silêncios. Renderizar com --concurrency=1.
export const R3V2_DUR = 54.0;
const VOZ = 0.3;
const t = (s: number) => s + VOZ;
const C = { s1: 0, s2: t(4.6), s3: t(11.5), s4: t(15.85), s5: t(23.55), s6: t(28.75), s7: t(38.45), s8: t(44.6), fim: R3V2_DUR };

const Tag: React.FC<{ nome: string; at: number; clara?: boolean }> = ({ nome, at, clara }) => {
  const f = useCurrentFrame();
  const p = mola(f, at, 12);
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 14, padding: "14px 26px", borderRadius: 999, background: clara ? "#FFFFFF" : TINTA, color: clara ? TINTA : "#FFFFFF", scale: String(p), transformOrigin: "0 50%", fontFamily: FONT, fontSize: 30, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase" }}>
      <IconeForca nome="Liberdade" cor={clara ? TINTA : "#FFFFFF"} tam={40} traco={4} />
      {nome}
    </div>
  );
};

// 1 · a foto nasce estreita e alarga quando a voz diz "margem"; duas réguas marcam as bordas
const Cena1: React.FC = () => {
  const f = useCurrentFrame();
  const abre = k(f, F(t(2.6)), F(t(2.6)) + 22, 0, 1, Easing.inOut(Easing.cubic));
  const entra = mola(f, 0.05, 18);
  // v3 (19/11): a foto aparece inteira desde o primeiro quadro (o o diretor achou que a foto estreita parecia cortada);
  // a ideia de "margem" ficou nas duas réguas, que nascem no meio e abrem até as bordas da foto
  const wr = 120 + (960 - 120) * abre;
  const lr = 540 - wr / 2;
  const regua = k(f, F(t(2.5)), F(t(2.5)) + 8);
  const v = Math.round(k(f, F(t(3.0)), F(t(4.2)), 0, 63));
  return (
    <Tela tom="claro">
      <Foto src="vita/nov/c4-aposta.jpg" a={0} b={C.s2} foco="45% 35%" raio={48} zoom={[1.15, 1.02]} style={{ left: 60, width: 960, top: 240, height: 1000, translate: `0px ${((1 - entra) * 300).toFixed(1)}px` }} />
      {[lr - 26, lr + wr + 10].map((x, i) => (
        <div key={i} style={{ position: "absolute", left: x, top: 260, width: 16, height: 960, opacity: regua * (1 - k(f, F(t(4.0)), F(t(4.0)) + 10)), display: "flex", flexDirection: "column", justifyContent: "space-between", alignItems: "center" }}>
          <div style={{ width: 16, height: 4, background: TINTA }} />
          <div style={{ flex: 1, width: 3, background: TINTA, opacity: 0.6 }} />
          <div style={{ width: 16, height: 4, background: TINTA }} />
        </div>
      ))}
      <div style={{ position: "absolute", left: 100, top: 1130, opacity: k(f, F(t(3.0)), F(t(3.0)) + 8) }}>
        <Pilula style={{ fontSize: 36 }}>
          <IconeForca nome="Liberdade" cor={TINTA} tam={44} traco={4} />
          Liberdade <b style={{ fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>{v}</b>
        </Pilula>
      </div>
      <div style={{ position: "absolute", left: LADO, right: LADO, top: 1330 }}>
        <Linhas tom="claro" size={84} linhas={["Liberdade é o tamanho", "da sua *margem", "*para *mudar."]} at={[t(0.88), t(2.35), t(3.23)]} />
      </div>
    </Tela>
  );
};

// 2 · tela dividida: o trabalho de hoje à esquerda, o "depois" tracejado à direita
const Cena2: React.FC = () => {
  const f = useCurrentFrame();
  const a = mola(f, C.s2 + 0.15, 16);
  const b = mola(f, t(9.37), 16);
  const seta = k(f, F(t(6.82)), F(t(6.82)) + 18, 0, 1, Easing.inOut(Easing.cubic));
  return (
    <Tela tom="escuro">
      <div style={{ position: "absolute", left: LADO, right: LADO, top: 250 }}>
        <Linhas tom="escuro" size={74} linhas={["Se você quisesse ou", "precisasse mudar de", "trabalho, teria *condição", "de fazer isso?"]} at={[t(4.77), t(5.84), t(7.31), t(9.9)]} />
      </div>
      <Foto src="vita/nov/c1-mito2.jpg" a={C.s2} b={C.s3} foco="50% 35%" raio={40} zoom={[1.1, 1.0]} cinza={0.15} style={{ left: 60, width: 450, top: 820, height: 680, translate: `${((1 - a) * -520).toFixed(1)}px 0px` }}>
        <div style={{ position: "absolute", left: 22, bottom: 22 }}><Pilula style={{ fontSize: 28, padding: "12px 24px" }}>hoje</Pilula></div>
      </Foto>
      <div style={{ position: "absolute", left: 570, width: 450, top: 820, height: 680, borderRadius: 40, border: `4px dashed rgba(255,254,252,0.55)`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 20, scale: String(0.8 + 0.2 * b), opacity: b }}>
        <span style={{ fontFamily: FONT, fontSize: 220, fontWeight: 700, color: PAPEL, lineHeight: 1 }}>?</span>
        <Pilula escura style={{ background: "rgba(255,255,255,0.12)", fontSize: 28, padding: "12px 24px" }}>depois</Pilula>
      </div>
      <svg width="120" height="60" viewBox="0 0 120 60" style={{ position: "absolute", left: 480, top: 1130 }}>
        <path d="M8 30 H100" stroke={PAPEL} strokeWidth={7} strokeLinecap="round" strokeDasharray="100" strokeDashoffset={100 * (1 - seta)} />
        <path d="M84 14 L106 30 L84 46" fill="none" stroke={PAPEL} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round" opacity={seta > 0.9 ? 1 : 0} />
      </svg>
    </Tela>
  );
};

// 3 · Finanças: foto cheia e uma folha branca sobe com os 12 meses; 4 acendem (exemplo)
const Cena3: React.FC = () => {
  const f = useCurrentFrame();
  const folha = mola(f, C.s3 + 0.2, 18);
  return (
    <Tela tom="claro" logoBranca>
      <Foto src="vita/nov/c5-q3.jpg" a={C.s3} b={C.s4} foco="50% 30%" raio={0} zoom={[1.12, 1.25]} style={{ inset: 0 }}>
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(20,22,21,0.35) 0%, rgba(20,22,21,0) 28%)" }} />
      </Foto>
      <div style={{ position: "absolute", left: LADO, top: 250 }}><Tag nome="Finanças" at={C.s3 + 0.1} clara /></div>
      <div style={{ position: "absolute", left: 40, right: 40, bottom: 40, background: PAPEL, borderRadius: 48, padding: "54px 50px 56px", translate: `0px ${((1 - folha) * 900).toFixed(1)}px` }}>
        <Linhas tom="claro" size={64} linhas={["Por quantos meses você", "conseguiria se sustentar", "sem *salário?"]} at={[t(11.75), t(12.28), t(14.06)]} />
        <div style={{ display: "grid", gridTemplateColumns: "repeat(6, 1fr)", gap: 14, marginTop: 40 }}>
          {Array.from({ length: 12 }).map((_, i) => {
            const p = mola(f, t(12.0) + i * 0.06, 10);
            const aceso = i < 4 ? k(f, F(t(13.33) + i * 0.25), F(t(13.33) + i * 0.25) + 8) : 0;
            return (
              <div key={i} style={{ height: 96, borderRadius: 22, background: aceso > 0.5 ? TINTA : "#ECEDEA", color: aceso > 0.5 ? "#FFFFFF" : CINZA, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT, fontSize: 32, fontWeight: 700, scale: String(p) }}>{i + 1}</div>
            );
          })}
        </div>
        <div style={{ display: "flex", alignItems: "baseline", gap: 16, marginTop: 30, fontFamily: FONT, opacity: k(f, F(t(14.3)), F(t(14.3)) + 8) }}>
          <span style={{ fontSize: 96, fontWeight: 700, color: TINTA, letterSpacing: "-0.05em", lineHeight: 1 }}>4 meses</span>
          <span style={{ fontSize: 30, fontWeight: 500, color: CINZA }}>de reserva · exemplo</span>
        </div>
      </div>
    </Tela>
  );
};

// 4 · Empregabilidade: você no centro e as pessoas de fora, em fotos, ligadas por linhas que se desenham
const REDE: [string, string, number, number][] = [
  ["vita/nov/c1-mito1.jpg", "50% 30%", -330, -330], ["vita/nov/c2-s2.jpg", "50% 30%", 330, -310],
  ["vita/nov/c1-intro.jpg", "50% 25%", -340, 330], ["vita/nov/c3-pdf.jpg", "50% 30%", 330, 340],
];
const Cena4: React.FC = () => {
  const f = useCurrentFrame();
  const cx = 540, cy = 1060;
  const centro = mola(f, C.s4 + 0.2, 16);
  return (
    <Tela tom="cinza">
      <div style={{ position: "absolute", left: LADO, top: 250 }}><Tag nome="Empregabilidade" at={C.s4 + 0.1} /></div>
      <div style={{ position: "absolute", left: LADO, right: LADO, top: 360 }}>
        <Linhas tom="cinza" size={66} linhas={["Como você avalia as suas", "chances de *recolocação?"]} at={[t(16.16), t(17.4)]} />
      </div>
      <svg width="1080" height="1920" style={{ position: "absolute", inset: 0 }}>
        {REDE.map(([, , dx, dy], i) => {
          const l = k(f, F(t(20.04) + i * 0.25), F(t(20.04) + i * 0.25) + 14, 0, 1, Easing.out(Easing.cubic));
          return <line key={i} x1={cx} y1={cy} x2={cx + dx * l} y2={cy + dy * l} stroke={TINTA} strokeWidth={4} strokeDasharray="10 10" opacity={0.6} />;
        })}
      </svg>
      {REDE.map(([src, foco, dx, dy], i) => {
        const p = mola(f, t(20.04) + i * 0.25 + 0.3, 12);
        return <Foto key={i} src={src} a={C.s4} b={C.s5} foco={foco} raio={34} zoom={[1.1, 1.0]} style={{ left: cx + dx - 110, top: cy + dy - 110, width: 220, height: 220, scale: String(p), boxShadow: "0 16px 34px rgba(20,22,21,0.16)" }} />;
      })}
      <Foto src="vita/nov/c5-q2.jpg" a={C.s4} b={C.s5} foco="50% 30%" raio={40} zoom={[1.12, 1.0]} style={{ left: cx - 190, top: cy - 240, width: 380, height: 480, scale: String(centro), boxShadow: "0 24px 50px rgba(20,22,21,0.22)" }}>
        <div style={{ position: "absolute", left: 18, bottom: 18 }}><Pilula escura style={{ fontSize: 26, padding: "10px 22px" }}>você</Pilula></div>
      </Foto>
      <div style={{ position: "absolute", left: LADO, right: LADO, top: 1560 }}>
        <Linhas tom="cinza" size={50} linhas={["E quem, fora da empresa,", "conhece o seu trabalho?"]} at={[t(20.04), t(21.07)]} />
      </div>
    </Tela>
  );
};

// 5 · Em casa: a foto de duas pessoas conversando; quem depende e quem apoia, em contagem
