// 6 · ampliar a margem: três faixas de foto empilham, e a barra da margem cresce a cada uma
const FAIXAS: [string, string, string, number][] = [
  ["vita/nov/c2-s2.jpg", "50% 45%", "Guardar dinheiro", t(34.15)],
  ["vita/nov/c3-pdf.jpg", "50% 45%", "Estudar", t(35.39)],
  ["vita/nov/c5-q1.jpg", "50% 30%", "Cuidar dos contatos de fora", t(36.36)],
];
const Cena6: React.FC = () => {
  const f = useCurrentFrame();
  const base = k(f, F(t(30.72)), F(t(30.72)) + 16, 0, 0.25);
  const deg = FAIXAS.reduce((s, [, , , at]) => s + k(f, F(at), F(at) + 12, 0, 0.23, Easing.out(Easing.back(1.3))), 0);
  return (
    <Tela tom="claro">
      <div style={{ position: "absolute", left: LADO, right: LADO, top: 240 }}>
        <Linhas tom="claro" size={64} linhas={["Dá para ampliar essa *margem", "aos poucos, dentro das", "suas condições:"]} at={[t(29.01), t(30.93), t(32.12)]} />
      </div>
      <div style={{ position: "absolute", left: LADO, right: LADO, top: 560 }}>
        <div style={{ fontFamily: FONT, fontSize: 26, fontWeight: 600, letterSpacing: "0.1em", textTransform: "uppercase", color: CINZA, marginBottom: 12 }}>Margem para mudar</div>
        <div style={{ height: 26, borderRadius: 26, background: "#ECEDEA" }}>
          <div style={{ width: `${(base + deg) * 100}%`, height: "100%", borderRadius: 26, background: TINTA }} />
        </div>
      </div>
      {FAIXAS.map(([src, foco, rot, at], i) => {
        const p = mola(f, at, 14);
        return (
          <Foto key={rot} src={src} a={at} b={C.s7} foco={foco} raio={40} zoom={[1.15, 1.02]} style={{ left: 60, right: 60, top: 700 + i * 360, height: 330, translate: `${((1 - p) * (i % 2 ? 1100 : -1100)).toFixed(1)}px 0px` }}>
