// VITA (SAPIANS) — kit dos reels "humanizados" (19/11/2026), pedido: o mesmo estilo dos carrosséis de
// novembro (fotos de pessoas reais, cartões de canto redondo, off-white, Figtree, logo no topo), com motion de verdade
// e sem cara de legenda: nada de caixinha atrás do texto. O texto sobe da linha por máscara e o destaque é o peso
// mais forte com um traço que se desenha embaixo. O fundo inverte (claro ↔ escuro) e cada cena entra com uma
// transição diferente (empurrar, inundar, abrir, aproximar, cortina).

export const FPS = 30;
export const F = (s: number) => Math.round(s * FPS);
export const PAPEL = "#FFFEFC";
export const PAPEL2 = "#F2F3EF";
export const TINTA = "#212322";
export const CINZA = "#606460";
export const LADO = 90;

export const k = (f: number, a: number, b: number, from = 0, to = 1, ease = Easing.out(Easing.cubic)) =>
  interpolate(f, [a, b], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
// mola curta, com no máximo ~4% de passagem
export const mola = (f: number, at: number, dur = 14) => k(f, F(at), F(at) + dur, 0, 1, Easing.out(Easing.back(1.25)));

export type Tom = "claro" | "cinza" | "escuro";
export const FUNDO: Record<Tom, string> = { claro: PAPEL, cinza: PAPEL2, escuro: TINTA };
export const TEXTO: Record<Tom, string> = { claro: TINTA, cinza: TINTA, escuro: PAPEL };

// texto que sobe da linha (máscara), uma linha por vez; `*palavra` = destaque (mais peso + traço desenhado embaixo)
export const Linhas: React.FC<{
  linhas: string[];
  at: number[];
  size: number;
  tom: Tom;
  peso?: number;
  centro?: boolean;
  style?: React.CSSProperties;
}> = ({ linhas, at, size, tom, peso = 500, centro, style }) => {
  const f = useCurrentFrame();
  const cor = TEXTO[tom];
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: centro ? "center" : "flex-start", fontFamily: FONT, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.035em", color: cor, ...style }}>
      {linhas.map((ln, i) => {
        const a = at[Math.min(i, at.length - 1)];
        const p = k(f, F(a), F(a) + 13, 0, 1, Easing.out(Easing.back(1.15)));
        const tr = k(f, F(a) + 8, F(a) + 22, 0, 1, Easing.inOut(Easing.cubic));
        const ws = ln.split(" ");
        return (
          <div key={i} style={{ overflow: "hidden", paddingBottom: size * 0.16, marginBottom: -size * 0.1 }}>
            <div style={{ translate: `0px ${((1 - p) * 115).toFixed(1)}%`, display: "flex", flexWrap: "wrap", justifyContent: centro ? "center" : "flex-start", columnGap: size * 0.25 }}>
              {ws.map((w, j) => {
                const forte = w.startsWith("*");
                const txt = forte ? w.slice(1) : w;
                const seguinte = ws[j + 1]?.startsWith("*");
                return (
                  <span key={j} style={{ position: "relative", fontWeight: forte ? 700 : peso }}>
                    {txt}
                    {forte ? (
                      <span style={{ position: "absolute", left: 0, right: seguinte ? -size * 0.25 : 0, bottom: size * 0.02, height: Math.max(4, size * 0.07), borderRadius: 99, background: cor, transformOrigin: "0 50%", scale: `${tr.toFixed(3)} 1`, opacity: 0.9 }} />
                    ) : null}
                  </span>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

// foto num cartão de canto redondo, com aproximação lenta (Ken Burns); `cinza` tira a cor
export const Foto: React.FC<{ src: string; a: number; b: number; foco?: string; raio?: number; zoom?: [number, number]; cinza?: number; style?: React.CSSProperties; children?: React.ReactNode }> = ({ src, a, b, foco = "50% 40%", raio = 48, zoom = [1.1, 1.0], cinza = 0, style, children }) => {
  const f = useCurrentFrame();
  const z = interpolate(f, [F(a), F(b)], zoom, { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <div style={{ position: "absolute", overflow: "hidden", borderRadius: raio, ...style }}>
      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: foco, scale: String(z), transformOrigin: foco, filter: cinza ? `grayscale(${cinza}) contrast(1.05)` : undefined }} />
      {children}
    </div>
  );
};

export const Logo: React.FC<{ tom: Tom; branca?: boolean }> = ({ tom, branca }) => (
  <Img src={staticFile("vita/sapians-nominal.png")} style={{ position: "absolute", left: "50%", top: 120, transform: "translateX(-50%)", height: 40, width: "auto", zIndex: 20, filter: tom === "escuro" || branca ? "none" : "brightness(0)", opacity: 0.92 }} />
);

export const Tela: React.FC<{ tom: Tom; children: React.ReactNode; logoBranca?: boolean }> = ({ tom, children, logoBranca }) => (
  <AbsoluteFill style={{ background: FUNDO[tom] }}>
    {children}
    <Logo tom={tom} branca={logoBranca} />
  </AbsoluteFill>
);

export const Pilula: React.FC<{ children: React.ReactNode; escura?: boolean; style?: React.CSSProperties }> = ({ children, escura, style }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: 14, borderRadius: 999, padding: "18px 32px", fontFamily: FONT, fontSize: 34, fontWeight: 600, letterSpacing: "-0.01em", background: escura ? TINTA : "#FFFFFF", color: escura ? "#FFFFFF" : TINTA, boxShadow: escura ? "none" : "0 10px 30px rgba(20,22,21,0.12)", ...style }}>{children}</div>
);

export const Check: React.FC<{ cor?: string; tam?: number }> = ({ cor = "#FFFFFF", tam = 26 }) => (
  <svg width={tam} height={tam * 0.78} viewBox="0 0 26 20" fill="none" stroke={cor} strokeWidth="3.6" strokeLinecap="round" strokeLinejoin="round"><path d="M2 10l7 7L24 2" /></svg>
);

// transições de entrada (a cena nova por cima da anterior, por TR segundos)
export type Entrada = "corte" | "empurra" | "empurraX" | "inunda" | "abre" | "aproxima" | "cortina" | "divide" | "desce" | "gira";
export const TR = 0.45;
export const estiloEntrada = (tipo: Entrada, f: number, a: number, origem: [number, number] = [50, 50]): React.CSSProperties => {
  if (tipo === "corte") return {};
  const p = k(f, F(a), F(a + TR), 0, 1, Easing.inOut(Easing.cubic));
  if (p >= 1) return {};
  if (tipo === "empurra") return { translate: `0px ${((1 - p) * 100).toFixed(2)}%` };
  if (tipo === "empurraX") return { translate: `${((1 - p) * 100).toFixed(2)}% 0px` };
  if (tipo === "inunda") return { clipPath: `circle(${(p * 150).toFixed(2)}% at ${origem[0]}% ${origem[1]}%)` };
  if (tipo === "abre") return { clipPath: `inset(${((1 - p) * 50).toFixed(2)}% 0% ${((1 - p) * 50).toFixed(2)}% 0% round ${((1 - p) * 80).toFixed(0)}px)` };
  if (tipo === "cortina") return { clipPath: `inset(${((1 - p) * 100).toFixed(2)}% 0% 0% 0%)` };
  // divide: abre do meio para os lados, como duas portas
  if (tipo === "divide") return { clipPath: `inset(0% ${((1 - p) * 50).toFixed(2)}% 0% ${((1 - p) * 50).toFixed(2)}%)` };
  // desce: a cena nova desce de cima
  if (tipo === "desce") return { translate: `0px ${((p - 1) * 100).toFixed(2)}%` };
  // gira: entra girando de leve a partir de um canto, como um cartão virando
  if (tipo === "gira") return { rotate: `${((1 - p) * -8).toFixed(2)}deg`, translate: `${((1 - p) * -60).toFixed(2)}% ${((1 - p) * 30).toFixed(2)}%`, transformOrigin: "0% 100%" };
  // aproxima: chega de perto e desfocada
  return { opacity: p, scale: String(1.25 - 0.25 * p), filter: p < 0.98 ? `blur(${((1 - p) * 18).toFixed(1)}px)` : undefined };
};

